  'title'=>'How to Use Freshdesk: Setup, Tickets and Automation',
  'seo_title'=>'How to Use Freshdesk: Setup, Tickets and SLAs',
  'description'=>'Learn to set up Freshdesk email, route tickets, configure SLA policies, publish help articles and export records with official steps for a safer rollout.',
  'url'=>'/freshdesk/how-to-use/','date'=>'2026-10-28','updated'=>'2026-10-28','status'=>'published','tool_name'=>'Freshdesk','breadcrumb_label'=>'How to Use',
  'additional_schema'=>[
   ['@type'=>'HowTo','@id'=>'https://toolboxkart.tech/freshdesk/how-to-use/#howto','name'=>'How to set up Freshdesk for customer support','description'=>'Configure the correct Freshdesk product, connect support email, organize tickets, set automation and SLAs, and test the workflow.','step'=>[
    ['@type'=>'HowToStep','position'=>1,'name'=>'Choose the correct Freshdesk product','text'=>'Confirm whether your team needs email-first Freshdesk or the broader Freshdesk Omni product.','url'=>'https://toolboxkart.tech/freshdesk/how-to-use/#step-1'],
    ['@type'=>'HowToStep','position'=>2,'name'=>'Connect the support email','text'=>'Add and verify the support address, configure forwarding and send a test email to confirm ticket creation.','url'=>'https://toolboxkart.tech/freshdesk/how-to-use/#step-2'],
    ['@type'=>'HowToStep','position'=>3,'name'=>'Organize agents and groups','text'=>'Create the groups, ownership rules and ticket fields your team needs before enabling automatic assignment.','url'=>'https://toolboxkart.tech/freshdesk/how-to-use/#step-3'],
    ['@type'=>'HowToStep','position'=>4,'name'=>'Build ticket creation rules','text'=>'Add a small number of automation rules with clear conditions and actions, then test each rule with a sample ticket.','url'=>'https://toolboxkart.tech/freshdesk/how-to-use/#step-4'],
    ['@type'=>'HowToStep','position'=>5,'name'=>'Set response and resolution targets','text'=>'Create SLA policies that reflect ticket priority, business hours and the response or resolution target.','url'=>'https://toolboxkart.tech/freshdesk/how-to-use/#step-5'],
    ['@type'=>'HowToStep','position'=>6,'name'=>'Test the customer journey','text'=>'Create test tickets from the channels you use, verify routing and SLA behavior, and correct the rules before launch.','url'=>'https://toolboxkart.tech/freshdesk/how-to-use/#step-6']
   ]]
